def A(titulo,*items): return {'k':'asignar','titulo':titulo,'items':[{'p':p,'op':op,'ok':ok,'why':why} for p,op,ok,why in items]}
def LL(titulo,antes,resp,unidad='',tol=1e-9,pista='',why=''): return {'k':'llenar','titulo':titulo,'antes':antes,'resp':resp,'unidad':unidad,'tol':tol,'pista':pista,'why':why}
def OR(titulo,items,why): return {'k':'ordenar','titulo':titulo,'items':items,'why':why}
